package com.fidecode.biteflow.application.printing;import com.fidecode.biteflow.application.printing.dto.*;import com.fidecode.biteflow.domain.printing.entity.*;public final class PrintingDtoMapper{private PrintingDtoMapper(){}public static PrinterResponse toResponse(Printer p){return new PrinterResponse(p.getId()!=null?p.getId().toString():null,p.getName(),p.getConnectionType(),p.getAddress(),p.isActive());}public static PrintRuleResponse toResponse(PrintRule r){return new PrintRuleResponse(r.getId()!=null?r.getId().toString():null,r.getName(),r.getOperation(),r.getDocumentType(),r.getSectorId()!=null?r.getSectorId().toString():null,r.getPrinterId().toString(),r.isActive());}}
